                    .owner
                    .clone()
                    .ok_or_else(|| replay_error(function, "lexical loop has no execution owner"))?;
                let target = crate::hir::ControlTarget::Loop {
                    owner,
                    site: work.clone_owned(&condition.id, "loop target site clone")?,
