    let leaves = crate::cleanup_plan::replay::collect_leaves(function).unwrap();
    let (required, refused, _, first) = with_limit_usage_refusal(LIMIT, || {
        let mut budget = ReplayBudget::new();
        let initial = budget.remaining;
        validate_exits(
