fn complete(
    program: &ResolvedProgram,
    function: &ResolvedFunction,
    old: bool,
) -> Result<(), Diagnostic> {
    let storage = crate::cleanup_plan::replay::validate_slots(function)?;
    let leaves = crate::cleanup_plan::replay::collect_leaves(function)?;
    if old {
